"""DELETE the AlphaDog Styles test listings created on Nov 14 2026 (owner: 'you can delete the others already done'). Only SKUs generated by our own feed; parents AMZ-P-*.
env AMZ_DELETE_IDS=amazon-tee-01,... Prints counts only."""
import json, os, urllib.request, collections
from concurrent.futures import ThreadPoolExecutor
import spapi, amz_validate as V
c = spapi.load_creds(V.HERE); seller = c.get("SELLER_ID") or "A3431QI59MY9RE"; MP = spapi.MARKETPLACE
ids = [x.strip() for x in os.environ["AMZ_DELETE_IDS"].split(",") if x.strip()]
feed = json.loads(urllib.request.urlopen(V.FEED + "?x=%d" % os.getpid(), timeout=120).read().decode())
stat = collections.Counter()
def rm(sku):
    import re
    assert sku.startswith("AMZ-P-") or re.match(r"^[A-Z]-[A-Z]{2}-\d-[A-Z]{2}(-\w+)?$", sku), sku  # AlphaDog SKUs only
    try:
        r = spapi.call(c, "DELETE", "/listings/2021-08-01/items/%s/%s" % (seller, sku), params={"marketplaceIds": MP, "issueLocale": "en_US"}); return r.get("status", "?")
    except spapi.SpError as e: return "404" if "404" in str(e) else "ERR " + str(e)[:80]
for F in feed:
    if F["id"] not in ids: continue
    with ThreadPoolExecutor(4) as ex: res = list(ex.map(rm, [k["sku"] for k in F["children"]]))
    pr = rm(F["parent_sku"]); print(F["id"], "children", dict(collections.Counter(res)), "parent", pr); stat.update(res)
print("TOTAL", dict(stat))
